#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: Magkano v1.1 owner setup (OpenAI, GitHub, Neon, Vercel, Clerk,
# GoDaddy). Source of truth: .scratch/v1.1/spec.md, "Owner setup wizard".
#
# Run:    deploy/setup.sh            (all 9 steps)
#         deploy/setup.sh --from 7   (resume at step 7)
#         deploy/setup.sh --list     (print the steps)
#         deploy/setup.sh --help
#
# NO SECRETS RULE: this wizard never reads, prints, writes or stores a secret.
# Keys go from one dashboard straight into another (or a password manager).
# The library's secret helpers are disabled just below, so a later edit can't
# quietly start capturing one. The only things it reads from the owner are
# public: an IP address shown by Vercel and a preview URL.
# ──────────────────────────────────────────────────────────────────────────

_no_secrets() {
  printf '  this wizard never captures secrets (%s is disabled)\n' "$1" >&2
  exit 70
}
ask_secret() { _no_secrets ask_secret; }
write_env()  { _no_secrets write_env; }
set_secret() { _no_secrets set_secret; }
set_var()    { _no_secrets set_var; }
# `ask` offers defaults from .env, which holds keys: read public values with
# ask_public instead.
ask() { _no_secrets ask; }

DOMAIN="magkano.online"
WWW="www.$DOMAIN"
REPO_SLUG="Jomari-Macaraig/magkano"
SAMPLE_RECIPE="sinigang-na-baboy"
GODADDY_DNS="https://dcc.godaddy.com/control/dnsmanagement?domainName=$DOMAIN"
STEP_TITLES=(
  ""
  "OpenAI: project, spend limit and API key"
  "GitHub: automatically delete head branches"
  "Neon: account and project"
  "Vercel: import the repo"
  "Neon-Managed integration"
  "Vercel: environment variables"
  "Clerk production and its DNS at GoDaddy"
  "Vercel: domains and DNS"
  "First deploys and acceptance checks"
)
LAST_STEP=9
FROM=1
CURRENT_STEP=0
OK_COUNT=0

ok() { printf '  %s✓ %s%s\n' "$GREEN" "$1" "$RESET"; OK_COUNT=$((OK_COUNT + 1)); }
have() { command -v "$1" >/dev/null 2>&1; }

usage() {
  cat <<EOF
Usage: deploy/setup.sh [--from N] [--list] [--help]

Walks the project owner through the Magkano v1.1 account setup, one step at a
time, and checks what it can from the terminal (dig, curl, the vercel and gh
CLIs when installed). It never reads, prints or stores a secret.

  --from N   start at step N (1-$LAST_STEP), e.g. after Clerk DNS has propagated
  --list     print the steps and exit
  --help     show this help

Steps:
EOF
  list_steps
}

list_steps() {
  local i
  for ((i = 1; i <= LAST_STEP; i++)); do printf '  %d. %s\n' "$i" "${STEP_TITLES[$i]}"; done
}

parse_args() {
  while (($#)); do
    case "$1" in
      -h | --help) usage; exit 0 ;;
      --list) list_steps; exit 0 ;;
      --from) [[ $# -ge 2 ]] || { echo "--from needs a step number" >&2; exit 64; }; FROM="$2"; shift ;;
      --from=*) FROM="${1#--from=}" ;;
      *) echo "Unknown option: $1 (try --help)" >&2; exit 64 ;;
    esac
    shift
  done
  if ! [[ "$FROM" =~ ^[0-9]+$ ]] || ((FROM < 1 || FROM > LAST_STEP)); then
    echo "--from must be a step number from 1 to $LAST_STEP" >&2
    exit 64
  fi
}

resume_hint() {
  if ((CURRENT_STEP > 0)); then
    printf '\n  %sResume later with:%s deploy/setup.sh --from %s\n\n' "$BOLD" "$RESET" "$CURRENT_STEP"
  fi
}

quit_wizard() {
  resume_hint
  exit 0
}

# begin N: start step N, numbered as in the spec even when resuming.
begin() {
  CURRENT_STEP="$1"
  _STAGE_INDEX=$(($1 - 1))
  stage "${STEP_TITLES[$1]}"
  printf '\n'
}

# ask_public "Prompt": prints a non-secret value (Enter leaves it empty).
ask_public() {
  local input=""
  read -e -r -p "  $1 " input || true
  printf '%s' "$input"
}

# skip_check "what": a tool is missing, so the owner checks this by hand.
skip_check() {
  warn "skipped: $1"
  SKIPPED+=("check by hand: $1")
}

# check "label" cmd args...: runs a check; on failure, retry, continue or quit.
check() {
  local label="$1" reply=""
  shift
  while true; do
    if "$@"; then
      ok "$label"
      return 0
    fi
    warn "check failed: $label"
    printf '  %s[r]etry, [c]ontinue anyway, [q]uit?%s ' "$YELLOW" "$RESET"
    read -r reply || reply=q
    case "$reply" in
      c | C) SKIPPED+=("failed check: $label (step $CURRENT_STEP)"); return 0 ;;
      q | Q) quit_wizard ;;
      *) note "retrying..." ;;
    esac
  done
}

# done_step: the pause that ends every step.
done_step() {
  printf '\n'
  pause "Step $CURRENT_STEP done? Press Enter for the next step (Ctrl-C to stop)."
}

# ── DNS checks (dig) ─────────────────────────────────────────────────────
# DNS_SERVER=1.1.1.1 deploy/setup.sh queries that resolver instead of yours.
_dig() {
  local args=(+short +time=3 +tries=2)
  [[ -n "${DNS_SERVER:-}" ]] && args+=("@$DNS_SERVER")
  dig "${args[@]}" "$@" 2>/dev/null || true
}

# dns_cname HOST SUBSTRING: HOST has a CNAME containing SUBSTRING.
dns_cname() {
  local out
  out=$(_dig CNAME "$1" | tr '\n' ' ')
  note "$1 CNAME → ${out:-(none)}"
  [[ -n "$out" && "$out" == *"$2"* ]]
}

# dns_no_caa: the apex has no CAA records (they could block Clerk or Vercel certs).
dns_no_caa() {
  local out
  out=$(_dig CAA "$DOMAIN" | tr '\n' ' ')
  note "$DOMAIN CAA → ${out:-(none)}"
  [[ -z "$out" ]]
}

# _words "a b": its words, sorted and de-duplicated, one line.
_words() { printf '%s\n' "$1" | tr ' ' '\n' | grep -v '^$' | sort -u | tr '\n' ' '; }

# dns_apex_a EXPECTED: the apex A records are exactly EXPECTED (any order), so
# GoDaddy's parked IPs fail this. Only IPv4 lines count, not dig's error text.
dns_apex_a() {
  local out
  out=$(_dig A "$DOMAIN" | grep -E '^[0-9]+(\.[0-9]+){3}$' | tr '\n' ' ' || true)
  note "$DOMAIN A → ${out:-(none)}"
  [[ -n "$out" && -n "$1" ]] || return 1
  [[ "$(_words "$out")" == "$(_words "$1")" ]]
}

# ── HTTP checks (curl) ───────────────────────────────────────────────────
# http_redirect URL TARGET: URL answers a 301/302/307/308 to TARGET.
http_redirect() {
  local out code loc
  out=$(curl -sS -o /dev/null --max-time 20 -w '%{http_code} %{redirect_url}' "$1" 2>&1) || true
  code="${out%% *}"
  loc="${out#* }"
  note "$1 → $out"
  [[ "$code" =~ ^30[1278]$ ]] && [[ "${loc%/}" == "${2%/}" ]]
}

# http_status URL CODE [CONTENT_TYPE_PART]: URL answers CODE (and that type).
http_status() {
  local out code ctype
  out=$(curl -sS -o /dev/null --max-time 30 -w '%{http_code} %{content_type}' "$1" 2>&1) || true
  code="${out%% *}"
  ctype="${out#* }"
  note "$1 → $out"
  [[ "$code" == "$2" ]] || return 1
  [[ -z "${3:-}" || "$ctype" == *"$3"* ]]
}

# http_health BASE: BASE/api/health returns {"status":"ok"}.
http_health() {
  local body
  body=$(curl -sS --max-time 30 "$1/api/health" 2>&1) || true
  note "$1/api/health → ${body:0:200}"
  [[ "$(printf '%s' "$body" | tr -d ' \n\r')" == '{"status":"ok"}' ]]
}

# http_body_has URL CODE TEXT: URL answers CODE with TEXT in its body.
http_body_has() {
  local tmp code
  tmp=$(mktemp)
  code=$(curl -sS -o "$tmp" --max-time 30 -w '%{http_code}' "$1" 2>/dev/null) || true
  note "$1 → $code $(head -c 160 "$tmp" | tr '\n' ' ')"
  if [[ "$code" == "$2" ]] && grep -qF "$3" "$tmp"; then rm -f "$tmp"; return 0; fi
  rm -f "$tmp"
  return 1
}

# app_checks BASE: acceptance checks 2 and 3 against a deployment.
app_checks() {
  local base="${1%/}"
  if ! have curl; then skip_check "curl is not installed: open $base/api/health in a browser"; return 0; fi
  check "$base/api/health returns {\"status\":\"ok\"}" http_health "$base"
  check "GET /api/recipes/$SAMPLE_RECIPE returns that Recipe (Hono sees the original path)" \
    http_body_has "$base/api/recipes/$SAMPLE_RECIPE" 200 "\"$SAMPLE_RECIPE\""
  check "GET /api/nope returns the JSON not_found error, not the SPA" \
    http_body_has "$base/api/nope" 404 '"not_found"'
  check "the deep link /recipes/$SAMPLE_RECIPE serves the SPA (index.html)" \
    http_status "$base/recipes/$SAMPLE_RECIPE" 200 "text/html"
}

# ── Vercel env checks (vercel CLI) ───────────────────────────────────────
# Names only: `vercel env ls` never shows values, and only the first column
# (the variable name) is kept.
vercel_ready() {
  have vercel && [[ -f .vercel/project.json ]]
}

# Fails (rather than listing nothing) when the CLI errors, e.g. when logged out.
vercel_env_names() {
  local out
  if ! out=$(vercel env ls "$1" </dev/null 2>/dev/null); then
    note "'vercel env ls $1' failed (logged out? run 'vercel login')" >&2
    return 1
  fi
  printf '%s\n' "$out" | awk 'NF && $1 ~ /^[A-Z_][A-Z0-9_]*$/ { print $1 }' | sort -u
}

# env_has ENV NAME...: every NAME exists in Vercel environment ENV.
env_has() {
  local env="$1" names name missing=0
  shift
  names=$(vercel_env_names "$env") || return 1
  for name in "$@"; do
    if grep -qx "$name" <<<"$names"; then note "$env: $name is set"
    else note "$env: $name is missing"; missing=1; fi
  done
  ((missing == 0))
}

# env_lacks_db ENV: Vercel environment ENV has no DATABASE_URL* of its own.
env_lacks_db() {
  local names found
  names=$(vercel_env_names "$1") || return 1
  found=$(printf '%s\n' "$names" | grep -E '^DATABASE_URL' | tr '\n' ' ' || true)
  note "$1: DATABASE_URL* vars → ${found:-(none)}"
  [[ -z "$found" ]]
}

# vercel_check "label" fn args...: a check that needs the linked vercel CLI.
vercel_check() {
  local label="$1"
  shift
  if ! have vercel; then
    skip_check "$label (vercel CLI not installed; see Vercel → Settings → Environment Variables)"
  elif [[ ! -f .vercel/project.json ]]; then
    skip_check "$label (repo not linked; run 'vercel link' to let the wizard check this)"
  else
    check "$label" "$@"
  fi
}

# ── GitHub check (gh CLI) ────────────────────────────────────────────────
gh_auto_delete_on() {
  local value
  value=$(gh repo view "$REPO_SLUG" --json deleteBranchOnMerge -q .deleteBranchOnMerge 2>/dev/null || true)
  note "deleteBranchOnMerge → ${value:-(unknown)}"
  [[ "$value" == "true" ]]
}

