# The 9 steps, in the spec's order.
# ──────────────────────────────────────────────────────────────────────────

step_1() {
  begin 1
  say "A public, unthrottled app needs a key that can't run up a big bill."
  open_url "https://platform.openai.com/settings/organization/projects"
  step "Settings → Organization → Projects → Create project. Name: ${BOLD}magkano${RESET}."
  step "Switch to the magkano project (project picker, top left)."
  step "Project settings → Limits: set a ${BOLD}monthly budget${RESET} (a few US dollars is plenty)."
  note "  The app only uses text-embedding-3-large. If Limits offers a model allowlist,"
  note "  you can allow just that model."
  step "Project → API keys → Create new secret key. Name it ${BOLD}magkano-vercel${RESET}, project magkano."
  warn "OpenAI shows the key once. Put it straight into your password manager."
  warn "Don't paste it here. You'll paste it into Vercel yourself in step 6."
  done_step
}

step_2() {
  begin 2
  say "Merged PR branches get deleted, so Neon can clean up their preview databases"
  say "(the Free plan caps a project at 10 branches)."
  open_url "https://github.com/$REPO_SLUG/settings"
  step "Settings → General → Pull Requests section."
  step "Tick ${BOLD}Automatically delete head branches${RESET}. It saves on its own."
  pause "Press Enter once it's ticked."
  if have gh && gh auth status >/dev/null 2>&1; then
    check "GitHub deletes head branches on merge" gh_auto_delete_on
  else
    skip_check "'Automatically delete head branches' is ticked (gh CLI missing or not logged in)"
  fi
  done_step
}

step_3() {
  begin 3
  say "A Neon account of your own (not one created through Vercel), on the Free plan."
  open_url "https://console.neon.tech/signup"
  step "Sign up (or sign in). Plan: ${BOLD}Free${RESET}."
  step "New Project:"
  step "  Project name: ${BOLD}magkano${RESET}"
  step "  Postgres version: ${BOLD}17${RESET} (matches local pgvector/pgvector:pg17)"
  step "  Cloud provider: ${BOLD}AWS${RESET}, region ${BOLD}Asia Pacific (Singapore), aws-ap-southeast-1${RESET}"
  warn "The region can't be changed later. Check it's Singapore before you create the project."
  step "Leave the default branch as ${BOLD}main${RESET} and the database empty. The first production"
  step "deploy migrates and seeds it."
  note "Don't copy any connection string: the integration in step 5 hands them to Vercel."
  done_step
}

step_4() {
  begin 4
  say "One Vercel project at the repo root, on the Hobby (non-commercial) plan."
  open_url "https://vercel.com/new"
  step "Sign up or log in. Plan: ${BOLD}Hobby${RESET}."
  step "Import Git Repository → connect GitHub → pick ${BOLD}$REPO_SLUG${RESET}."
  step "Project name: ${BOLD}magkano${RESET}. Framework Preset: ${BOLD}Vite${RESET}."
  step "Root Directory: leave it as the repo root (${BOLD}./${RESET})."
  step "Build and Output Settings: change nothing. vercel.json sets the build command and"
  step "the output directory (apps/web/dist). Install command: leave the default (pnpm)."
  step "Environment Variables: add none here (steps 5 and 6 do it)."
  step "Click Deploy. ${BOLD}It's fine if this first deploy fails${RESET}: nothing is configured yet."
  printf '\n'
  say "Optional: link this checkout so the wizard can check Vercel env vars for you."
  note "  'vercel link' writes .vercel/project.json (IDs only, no secrets) and adds .vercel"
  note "  to .gitignore."
  warn "If it offers to pull environment variables (.env.local), answer No: that would"
  warn "write keys to disk."
  if have vercel; then
    if vercel_ready; then
      ok "this checkout is already linked to a Vercel project"
    elif confirm "Run 'vercel link' now (it asks you to log in if needed)?"; then
      vercel link || warn "vercel link didn't finish. Re-run it by hand any time."
    fi
  else
    note "  The vercel CLI isn't installed (npm i -g vercel). The env checks will be skipped."
  fi
  done_step
}

step_5() {
  begin 5
  say "Neon gives every preview its own database branch and production the main branch."
  open_url "https://console.neon.tech/app/projects"
  step "Open project magkano → ${BOLD}Integrations${RESET} → ${BOLD}Vercel${RESET} (the Neon-Managed one, not"
  step "Vercel's own Marketplace/Storage Neon) → Add. Approve the install on Vercel."
  step "Pick the Vercel project ${BOLD}magkano${RESET}."
  step "Environments: tick ${BOLD}Production${RESET} and ${BOLD}Preview${RESET}. ${BOLD}Leave Development unticked${RESET}."
  step "Turn on ${BOLD}Automatically delete obsolete Neon branches${RESET} (automatic branch cleanup)."
  step "If offered on Vercel's side, turn on Required → Preview and"
  step "'Resource must be active before deployment'."
  printf '\n'
  say "Now confirm the scoping in Vercel:"
  open_url "https://vercel.com/dashboard"
  step "Project magkano → Settings → Environment Variables."
  step "DATABASE_URL and DATABASE_URL_UNPOOLED must be ${BOLD}Production only${RESET}."
  step "Preview must have ${BOLD}no DATABASE_URL* of its own${RESET}: Neon injects one per deployment."
  step "Delete any DATABASE_URL* that lists Preview or Development."
  pause "Press Enter to check."
  vercel_check "Production has DATABASE_URL and DATABASE_URL_UNPOOLED" \
    env_has production DATABASE_URL DATABASE_URL_UNPOOLED
  vercel_check "Preview has no DATABASE_URL* of its own" env_lacks_db preview
  vercel_check "Development has no DATABASE_URL* (integration not connected there)" env_lacks_db development
  done_step
}

step_6() {
  begin 6
  say "Set the keys you have now. The production Clerk key comes in step 7."
  open_url "https://vercel.com/dashboard"
  step "Project magkano → Settings → Environment Variables → Add."
  step "${BOLD}OPENAI_API_KEY${RESET}: paste the key from step 1 (from your password manager)."
  step "  Environments: ${BOLD}Production${RESET} and ${BOLD}Preview${RESET} (not Development). Mark it Sensitive."
  step "${BOLD}VITE_CLERK_PUBLISHABLE_KEY${RESET} = your ${BOLD}pk_test_…${RESET} key."
  step "  Environments: ${BOLD}Preview only${RESET}."
  note "  It's the development instance key: Clerk Dashboard → (Development) → Configure"
  note "  → API keys, or the value in your local .env."
  warn "Don't set VITE_CLERK_PUBLISHABLE_KEY for Production yet. The pk_live_ key"
  warn "doesn't exist until you make the Clerk production instance in step 7."
  note "Never paste a key into this terminal."
  pause "Press Enter to check."
  vercel_check "Preview has OPENAI_API_KEY and VITE_CLERK_PUBLISHABLE_KEY" \
    env_has preview OPENAI_API_KEY VITE_CLERK_PUBLISHABLE_KEY
  vercel_check "Production has OPENAI_API_KEY" env_has production OPENAI_API_KEY
  note "The CLI can't show values: check by eye that Preview's key starts with pk_test_."
  done_step
}

step_7() {
  begin 7
  say "Clerk production runs only on your own domain. Its DNS can take up to 48 hours,"
  say "so it comes before the Vercel domain. Re-run with --from 7 to check it later."
  open_url "https://dashboard.clerk.com"
  step "Open the magkano application. In the instance switcher (top), choose"
  step "${BOLD}Create production instance${RESET}, and clone the development settings."
  step "Application domain: ${BOLD}$DOMAIN${RESET} (the bare domain, no www)."
  step "Configure → User & authentication: ${BOLD}email only${RESET}, as on the dev instance."
  step "  Turn off any social connection: production would need your own OAuth app."
  step "Configure → Domains: turn on ${BOLD}Allowed subdomains${RESET} and list only"
  step "  ${BOLD}$WWW${RESET}. The primary domain is always allowed."
  printf '\n'
  say "Add every DNS record from Clerk's Domains page at GoDaddy:"
  open_url "$GODADDY_DNS"
  step "Add → CNAME for each record Clerk lists: ${BOLD}clerk${RESET}, ${BOLD}accounts${RESET}, ${BOLD}clkmail${RESET},"
  step "  and the DKIM ones (usually ${BOLD}clk._domainkey${RESET} and ${BOLD}clk2._domainkey${RESET})."
  note "  GoDaddy's Name field takes only the label (clerk), not clerk.$DOMAIN."
  note "  Copy each value exactly from Clerk. TTL: the default is fine."
  step "Recommended: a TXT record ${BOLD}_dmarc${RESET} with value ${BOLD}v=DMARC1; p=none;${RESET}"
  step "  (without DMARC, Gmail may reject Clerk's sign-in emails)."
  step "Add no CAA record and no * wildcard record. Don't touch the apex or www yet."
  pause "Press Enter once the records are saved at GoDaddy."
  if have dig; then
    check "clerk.$DOMAIN CNAME points at Clerk" dns_cname "clerk.$DOMAIN" "clerk.services"
    check "accounts.$DOMAIN CNAME points at Clerk" dns_cname "accounts.$DOMAIN" "clerk.services"
    check "clkmail.$DOMAIN CNAME points at Clerk" dns_cname "clkmail.$DOMAIN" "clerk.services"
    check "clk._domainkey.$DOMAIN (DKIM) CNAME points at Clerk" dns_cname "clk._domainkey.$DOMAIN" "clerk.services"
    check "clk2._domainkey.$DOMAIN (DKIM) CNAME points at Clerk" dns_cname "clk2._domainkey.$DOMAIN" "clerk.services"
    check "$DOMAIN has no CAA records" dns_no_caa
    note "If Clerk listed different DKIM names, check those in the Dashboard instead."
  else
    skip_check "Clerk CNAMEs (dig not installed): clerk., accounts., clkmail. and DKIM"
  fi
  printf '\n'
  step "Back in Clerk → Domains: wait until every record shows ${BOLD}Verified${RESET}, then"
  step "click ${BOLD}Deploy certificates${RESET}."
  note "Waiting on DNS? Press Ctrl-C now and come back with: deploy/setup.sh --from 7"
  pause "Press Enter once the certificates are deployed."
  printf '\n'
  say "${BOLD}Now finish step 6${RESET}: the production key exists."
  step "Clerk Dashboard → (Production) → Configure → API keys → copy the ${BOLD}pk_live_…${RESET} key."
  step "Vercel → magkano → Settings → Environment Variables → Add"
  step "  ${BOLD}VITE_CLERK_PUBLISHABLE_KEY${RESET} = pk_live_…, Environments: ${BOLD}Production only${RESET}."
  pause "Press Enter to check."
  vercel_check "Production has VITE_CLERK_PUBLISHABLE_KEY (pk_live_)" \
    env_has production VITE_CLERK_PUBLISHABLE_KEY
  note "Check by eye that Production's key starts with pk_live_ and Preview's with pk_test_."
  done_step
}

step_8() {
  begin 8
  say "$DOMAIN is canonical. $WWW and http:// redirect to https://$DOMAIN."
  open_url "https://vercel.com/dashboard"
  step "Project magkano → Settings → Domains → Add Domain → ${BOLD}$DOMAIN${RESET}."
  step "Pick the option that adds ${BOLD}$WWW${RESET} as a ${BOLD}redirect to $DOMAIN${RESET} (308)."
  note "  If www got added the other way round, edit $WWW → Redirect to $DOMAIN."
  step "Each domain card shows the DNS record it needs. Keep this tab open."
  printf '\n'
  say "At GoDaddy, swap the parked records for Vercel's:"
  open_url "$GODADDY_DNS"
  step "A record ${BOLD}@${RESET} (GoDaddy's parked one) → edit its value to the IP Vercel shows"
  step "  (often 76.76.21.21). Delete any other A record on @."
  step "CNAME ${BOLD}www${RESET} (default value @) → edit its value to the one Vercel shows"
  step "  (ends in vercel-dns.com)."
  step "GoDaddy → Domain → ${BOLD}Forwarding${RESET}: remove any forwarding for $DOMAIN."
  step "Leave the Clerk records from step 7 alone. No CAA, no * wildcard."
  printf '\n'
  local vercel_ip=""
  if have dig; then
    vercel_ip=$(ask_public "Type the apex A value Vercel shows (public IP, or Enter to skip):")
    vercel_ip=$(printf '%s' "$vercel_ip" | tr -d '[:space:]')
    if [[ -n "$vercel_ip" ]]; then
      check "$DOMAIN A record points at Vercel ($vercel_ip)" dns_apex_a "$vercel_ip"
    else
      skip_check "$DOMAIN A record is Vercel's IP, not GoDaddy's parked one (no IP given)"
    fi
    check "$WWW CNAME points at Vercel" dns_cname "$WWW" "vercel-dns"
  else
    skip_check "apex A and www CNAME at GoDaddy (dig not installed)"
  fi
  step "Wait for Vercel's domain cards to say ${BOLD}Valid Configuration${RESET} (it then issues"
  step "the TLS certificates)."
  pause "Press Enter to check the redirects."
  if have curl; then
    check "https://$WWW redirects to https://$DOMAIN" http_redirect "https://$WWW/" "https://$DOMAIN/"
    check "http://$DOMAIN redirects to https://$DOMAIN" http_redirect "http://$DOMAIN/" "https://$DOMAIN/"
  else
    skip_check "www and http:// redirects (curl not installed)"
  fi
  done_step
}

step_9() {
  begin 9
  say "Needs the v1.1 code (vercel.json, api/index.ts) merged to main."
  open_url "https://vercel.com/dashboard"
  step "Project magkano → Deployments → the latest Production deployment from ${BOLD}main${RESET} →"
  step "  ⋯ → ${BOLD}Redeploy${RESET}. (Or merge to main, which deploys production.)"
  step "In its build log, check lint, typecheck, test, migrate, seed and the web build pass."
  step "  The migrate and seed lines must say ${BOLD}env=production${RESET} and Neon main's host."
  pause "Press Enter once the production deploy is Ready."
  printf '\n'
  say "Open a test PR to get a preview (run these yourself):"
  note "  git switch -c test/preview-check main"
  note "  git commit --allow-empty -m 'Test the preview deploy'"
  note "  git push -u origin test/preview-check && gh pr create --fill"
  step "In the preview's build log: migrate and seed say ${BOLD}env=preview${RESET} and a"
  step "  ${BOLD}preview/…${RESET} Neon host."
  local preview=""
  preview=$(ask_public "Paste the preview URL (https://…vercel.app, public; Enter to skip):")
  preview=$(printf '%s' "$preview" | tr -d '[:space:]')
  if [[ -n "$preview" ]]; then
    note "Vercel protects previews by default: a 401 here means checking in your"
    note "logged-in browser instead (then choose 'continue')."
    app_checks "$preview"
  else
    skip_check "preview acceptance checks 2 and 3 (no preview URL given)"
  fi
  printf '\n'
  say "By hand on the preview:"
  step "Search \"manok\": results with no \"basic search\" note. Price a Draft."
  step "Sign in with the dev instance (pk_test_)."
  step "Push again to the PR: the Neon console shows the same preview/<branch> (no new one)."
  step "Merge the PR (GitHub deletes the branch). On the next preview deploy, Neon"
  step "  removes that old branch."
  pause "Press Enter for the production checks."
  printf '\n'
  say "Production:"
  app_checks "https://$DOMAIN"
  if have curl; then
    check "https://$DOMAIN loads" http_status "https://$DOMAIN/" 200 "text/html"
    check "https://$WWW redirects to https://$DOMAIN" http_redirect "https://$WWW/" "https://$DOMAIN/"
    check "http://$DOMAIN redirects to https://$DOMAIN" http_redirect "http://$DOMAIN/" "https://$DOMAIN/"
  else
    skip_check "https://$DOMAIN loads, and the www and http:// redirects (curl not installed)"
  fi
  open_url "https://$DOMAIN"
  step "Sign up and sign in with email (the pk_live_ key). Search and price a Draft."
  note "Record the acceptance results on the first-deploy ticket."
  done_step
}

run_wizard() {
  parse_args "$@"
  cd "$(dirname "${BASH_SOURCE[0]}")/.."
  trap 'printf "\n"; resume_hint; exit 130' INT

  TOTAL_STAGES=$LAST_STEP

  _clear
  printf '\n%s%s  Magkano v1.1: owner setup%s\n' "$BOLD" "$BLUE" "$RESET"
  printf '%s  %s steps, starting at step %s%s\n\n' "$DIM" "$TOTAL_STAGES" "$FROM" "$RESET"
  say "You do each step in the browser; this wizard says exactly where to click and"
  say "checks what it can from here (dig, curl, the vercel and gh CLIs if installed)."
  say "It never asks for a key. Paste keys only into the dashboards themselves."
  say "Stop any time with Ctrl-C and resume with: deploy/setup.sh --from N"
  printf '\n'
  list_steps
  printf '\n'
  for tool in dig curl vercel gh; do
    have "$tool" || note "  $tool not found: its checks will be skipped (do them by eye)."
  done
  pause "Ready to start?"

  ((FROM <= 1)) && step_1
  ((FROM <= 2)) && step_2
  ((FROM <= 3)) && step_3
  ((FROM <= 4)) && step_4
  ((FROM <= 5)) && step_5
  ((FROM <= 6)) && step_6
  ((FROM <= 7)) && step_7
  ((FROM <= 8)) && step_8
  step_9

  CURRENT_STEP=0
  finish
  note "$OK_COUNT check(s) passed."
  printf '\n'
}

run_wizard "$@"; exit
